export function mapAsset(file, baseUrl = import.meta.env?.BASE_URL ?? '/') {
  const normalized = file.replace(/\.png$/, '.webp');
  const base = baseUrl.endsWith('/') ? baseUrl : `${baseUrl}/`;
  return `${base}assets/${mapFiles.has(normalized) ? 'map/' : ''}${normalized}`;
}
